package com.mantou.salesdialer.contacts;
public final class EnterpriseTimerCheck {static int n;static void ok(boolean b){n++;if(!b)throw new AssertionError("enterprise timer "+n);}public static void main(String[] args){long monday=java.time.Instant.parse("2026-10-19T01:00:00Z").toEpochMilli(),sunday=monday-86400000;var t=new EnterpriseTimerTicket(1,monday+5000,monday,sunday,10000,"boot","a".repeat(32),"b".repeat(64),"QUEUE-00000000-0000-0000-0000-000000000001","c".repeat(64));ok(t.status(sunday+4999,14999,"boot","b".repeat(64),1).equals("EARLY_TIMER"));ok(t.status(sunday+5000,15000,"boot","b".repeat(64),1).equals("DUE"));ok(t.status(sunday+35000,45000,"boot","b".repeat(64),1).equals("DUE"));ok(t.status(sunday+35001,45001,"boot","b".repeat(64),1).equals("EXPIRED"));ok(t.status(sunday+9000,15000,"boot","b".repeat(64),1).equals("TIMER_CLOCK_CHANGED"));ok(t.status(sunday+5000,15000,"other","b".repeat(64),1).equals("TIMER_CLOCK_CHANGED"));ok(t.status(sunday+5000,15000,"boot","d".repeat(64),1).equals("OWNER_CHANGED"));ok(t.status(sunday+5000,15000,"boot","b".repeat(64),2).equals("STALE_TIMER"));try{new EnterpriseTimerTicket(1,sunday+5000,sunday,sunday,10000,"boot","a".repeat(32),"b".repeat(64),t.queueId,"c".repeat(64));throw new AssertionError("Sunday business window accepted");}catch(IllegalArgumentException e){n++;}var x=new EnterpriseTimerTicket(1,sunday+5000,sunday,sunday,10000,"boot","a".repeat(32),"b".repeat(64),t.queueId,"c".repeat(64),true);ok(x.status(sunday+5000,15000,"boot","b".repeat(64),1).equals("DUE"));ok(x.status(sunday+35001,45001,"boot","b".repeat(64),1).equals("EXPIRED"));ok(x.status(sunday+9000,15000,"boot","b".repeat(64),1).equals("TIMER_CLOCK_CHANGED"));ok(x.status(sunday+5000,15000,"reboot","b".repeat(64),1).equals("TIMER_CLOCK_CHANGED"));ok(x.status(sunday+5000,15000,"boot","b".repeat(64),2).equals("STALE_TIMER"));System.out.println("EnterpriseTimerCheck passed "+n+" assertions");}}
